package brd14

// The virtual clock (docs/contract.md § Extensions; docs/research/virtual-clock.md).
//
// A generator's cell ts<<12|seq is a hybrid logical clock for local events; Observe is its
// receive rule. These tests are the Go half of the first evidence:
//
//   - vectors/clock.tsv, generated by the oracle, replayed through a generator driven by a
//     virtual clock: generators are differential-tested, and Python replays the same file;
//   - a fleet of generators with skewed clocks exchanging messages: every reply sorts after
//     the message it answers, and each node's virtual time stays within the bound the
//     research derives (2ε with message delays of at least 1 ms);
//   - the textbook HLC receive rule (match the observed cell) run on the same fleet: it breaks
//     the order, because a snowflake orders by ts|node|seq and the cell by ts|seq;
//   - one far-future id cannot drag the clock forward: Observe refuses it.

import (
	"fmt"
	"strconv"
	"strings"
	"testing"
)

// vclock is a settable virtual clock in Unix milliseconds.
type vclock struct{ ms int64 }

func (c *vclock) now() int64 { return c.ms }

func fnv1a64(s string) uint64 {
	h := uint64(0xcbf29ce484222325)
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 0x100000001b3
	}
	return h
}

func TestVirtualClockVectors(t *testing.T) {
	rows := vectorRows(t, "clock.tsv", 10)
	if len(rows) == 0 {
		t.Fatal("clock.tsv has no rows")
	}
	for _, r := range rows {
		name := r[0]
		node, _ := strconv.ParseUint(r[1], 10, 64)
		start, _ := strconv.ParseInt(r[2], 10, 64)
		clk := &vclock{ms: start}
		g := NewGeneratorWithClock(node, clk.now)
		var ids []string
		var verdicts strings.Builder
		var first, last uint64
		count := 0
		for _, tok := range strings.Split(r[3], ",") {
			switch tok[0] {
			case 't':
				clk.ms, _ = strconv.ParseInt(tok[1:], 10, 64)
			case 'm':
				k, _ := strconv.Atoi(tok[1:])
				for i := 0; i < k; i++ {
					s := g.Next()
					if count == 0 {
						first = s
					} else if s <= last {
						t.Fatalf("%s: id %d after %d is not increasing", name, s, last)
					}
					last = s
					count++
					ids = append(ids, strconv.FormatUint(s, 10))
				}
			case 'o':
				snowS, aheadS, _ := strings.Cut(tok[1:], "~")
				snow, _ := strconv.ParseUint(snowS, 10, 64)
				ahead, _ := strconv.ParseInt(aheadS, 10, 64)
				ok, err := g.Observe(snow, ahead)
				if err != nil {
					t.Fatalf("%s: Observe(%d): %v", name, snow, err)
				}
				if ok {
					verdicts.WriteByte('1')
				} else {
					verdicts.WriteByte('0')
				}
			}
		}
		got := []string{strconv.Itoa(count), "-", "-", fmt.Sprintf("%016x", fnv1a64(strings.Join(ids, ","))), "-",
			strconv.FormatInt(g.VirtualUnixMs(), 10)}
		if count > 0 {
			got[1], got[2] = strconv.FormatUint(first, 10), strconv.FormatUint(last, 10)
		}
		if verdicts.Len() > 0 {
			got[4] = verdicts.String()
		}
		want := r[4:10]
		for i, col := range []string{"count", "first", "last", "digest", "verdicts", "virtual_ms"} {
			if got[i] != want[i] {
				t.Errorf("%s: %s = %s, want %s", name, col, got[i], want[i])
			}
		}
	}
}

// fleet simulates n nodes whose physical clocks are skewed within ±skew of true time.
// Messages carry the sender's freshly minted id; on delivery the receiver applies receive
// and mints a reply. It reports every (message, reply) pair and the worst drift observed.
type fleetResult struct {
	pairs, violations int
	maxDrift          int64 // max over deliveries of VirtualUnixMs − the receiver's physical ms
}

func runFleet(n int, skew, minDelay, maxDelay int64, steps int, receive func(g *Generator, snow uint64)) fleetResult {
	rng := uint64(0x0B4D14_00C10C)
	next := func() uint64 { // SplitMix64
		rng += 0x9E3779B97F4A7C15
		z := rng
		z = (z ^ z>>30) * 0xBF58476D1CE4E5B9
		z = (z ^ z>>27) * 0x94D049BB133111EB
		return z ^ z>>31
	}
	const t0 = EpochMs + 65_459_497_641
	trueMs := int64(t0)
	clocks := make([]*vclock, n)
	offsets := make([]int64, n)
	gens := make([]*Generator, n)
	for i := range gens {
		offsets[i] = int64(next()%uint64(2*skew+1)) - skew
		clocks[i] = &vclock{ms: trueMs + offsets[i]}
		// Node numbers spread over the whole 10-bit range, so same-ms replies from lower
		// nodes occur — the case the textbook rule gets wrong.
		gens[i] = NewGeneratorWithClock(uint64(i*1023/(n-1)), clocks[i].now)
	}
	type msg struct {
		at   int64
		to   int
		snow uint64
	}
	var inflight []msg
	var res fleetResult
	for step := 0; step < steps; step++ {
		// Time moves 0 or 1 ms per step: many events share a millisecond.
		trueMs += int64(next() % 2)
		for i := range clocks {
			clocks[i].ms = trueMs + offsets[i]
		}
		// Deliver what is due.
		kept := inflight[:0]
		for _, m := range inflight {
			if m.at > trueMs {
				kept = append(kept, m)
				continue
			}
			g := gens[m.to]
			receive(g, m.snow)
			reply := g.Next()
			res.pairs++
			if reply <= m.snow {
				res.violations++
			}
			if d := g.VirtualUnixMs() - clocks[m.to].ms; d > res.maxDrift {
				res.maxDrift = d
			}
		}
		inflight = kept
		// A random node mints and sends to a random other node.
		from := int(next() % uint64(n))
		to := int(next() % uint64(n-1))
		if to >= from {
			to++
		}
		delay := minDelay + int64(next()%uint64(maxDelay-minDelay+1))
		inflight = append(inflight, msg{at: trueMs + delay, to: to, snow: gens[from].Next()})
	}
	return res
}

// observeBump is the library's receive rule with a bound wide enough never to refuse here.
func observeBump(g *Generator, snow uint64) {
	if ok, err := g.Observe(snow, 1<<40); !ok || err != nil {
		panic(fmt.Sprint("Observe refused a fleet message: ", ok, err))
	}
}

// observeNaive is the textbook HLC receive rule transplanted onto brd14: raise the cell to
// the observed id's cell (ts<<12|seq). Test-only — it is what the library must NOT do.
func observeNaive(g *Generator, snow uint64) {
	target := int64(snow>>22)<<seqBits | int64(snow&seqMask)
	for {
		last := g.cell.Load()
		if last >= target || g.cell.CompareAndSwap(last, target) {
			return
		}
	}
}

func TestObserveOrdersRepliesAcrossNodes(t *testing.T) {
	const skew = 50
	r := runFleet(16, skew, 0, 20, 200_000, observeBump)
	if r.violations != 0 {
		t.Fatalf("%d of %d replies sort before the message they answer", r.violations, r.pairs)
	}
	t.Logf("%d message/reply pairs over 16 nodes, ±%d ms skew, 0–20 ms delays: 0 out of order; max drift %d ms",
		r.pairs, skew, r.maxDrift)
}

func TestTextbookReceiveRuleBreaksOrder(t *testing.T) {
	r := runFleet(16, 50, 0, 20, 200_000, observeNaive)
	if r.violations == 0 {
		t.Fatal("the textbook rule produced no out-of-order reply; the fleet does not exercise same-ms lower-node replies")
	}
	t.Logf("textbook rule: %d of %d replies sort BEFORE the message they answer", r.violations, r.pairs)
}

// TestVirtualDriftBound: with every message delayed at least 1 ms and no burst past 4096
// ids/ms, every id minted at true time t carries a millisecond ≤ t + skew (by induction: a
// mint reads its own clock, or follows an id received at least 1 ms after it was minted).
// A reply's millisecond is the receiver's virtual time, and the receiver's own clock reads at
// least t − skew, so the drift is at most 2·skew (docs/research/virtual-clock.md, the bound).
// The bound is tight: a sender at +skew and a receiver at −skew reach it.
func TestVirtualDriftBound(t *testing.T) {
	for _, skew := range []int64{0, 5, 50, 500} {
		r := runFleet(16, skew, 1, 20, 100_000, observeBump)
		if r.violations != 0 {
			t.Fatalf("skew %d: %d out-of-order replies", skew, r.violations)
		}
		if bound := 2 * skew; r.maxDrift > bound {
			t.Fatalf("skew %d: max drift %d ms exceeds the bound 2·skew = %d", skew, r.maxDrift, bound)
		}
		t.Logf("skew ±%d ms: max drift %d ms (bound %d)", skew, r.maxDrift, 2*skew)
	}
}

func TestObserveRefusesTheFarFuture(t *testing.T) {
	clk := &vclock{ms: EpochMs + 65_459_497_641}
	g := NewGeneratorWithClock(5, clk.now)
	before := g.VirtualUnixMs()
	far := uint64(65_459_497_641+5_000) << 22 // 5 s ahead of this node's clock
	if ok, err := g.Observe(far, 1000); ok || err != nil {
		t.Fatalf("Observe of an id 5 s ahead with a 1 s bound = %v, %v; want refused", ok, err)
	}
	if g.VirtualUnixMs() != before {
		t.Fatal("a refused Observe moved the clock")
	}
	// Within the bound the cell moves to the last slot of the observed millisecond: the
	// virtual time is that millisecond, and the next mint lands in the one after it.
	if ok, _ := g.Observe(far, 10_000); !ok || g.VirtualUnixMs() != EpochMs+65_459_497_641+5_000 {
		t.Fatalf("within the bound the virtual time is the observed ms, got %d", g.VirtualUnixMs())
	}
	if next := g.Next(); next>>22 != 65_459_497_641+5_001 || next <= far {
		t.Fatalf("the next mint after Observe is %d (ms %d), want ms %d and > %d", next, next>>22, 65_459_497_641+5_001, far)
	}
	if _, err := g.Observe(1<<63, 1<<40); err != ErrRange {
		t.Fatalf("Observe(2^63) = %v, want ErrRange", err)
	}
}
